468	pub async fn rotate_read_on_scope_exit(
469	    fs: &mut crate::CipherBoxFS,
470	    grant_root_ipns_name: &str,
471	    deleted_child_id: &str,
472	    root_children_override: Option<Vec<SealedChildRef>>,
473	) -> Result<(), RotationError> {
474	    // ipns_name (read plane) and child UUID (write plane) are PUBLIC
475	    // identifiers, not key material — safe to log (CLAUDE.md rule 2).
476	    let Some((root_node_id, root_read_key)) =
477	        crate::write_ops::rotation_deps::find_grant_root_state(&fs.inodes, grant_root_ipns_name)
478	    else {
479	        return Err(RotationError::RotateFailed(format!(
480	            "rotate_read_on_scope_exit: grant-root {grant_root_ipns_name} not found in the \
481	             local inode table (write-plane child_id={deleted_child_id})"
482	        )));
483	    };
484	
485	    // Scope the immutable `deps` borrow of `fs` so it is dropped BEFORE the
486	    // post-rotation `&mut fs.inodes` refresh below (no overlapping borrows).
487	    let outcome = {
488	        let deps = crate::write_ops::rotation_deps::FuseRotationDeps::new(
489	            crate::write_ops::rotation_deps::ApiClientTransport {
490	                api: fs.api.as_ref(),
491	                inodes: &fs.inodes,
492	            },
493	            fs.public_key.to_vec(),
494	            fs.private_key.to_vec(),
495	            fs.rotation_checkpoint_store.clone(),
496	        );
497	        let mut job = cipherbox_sdk::RotationJobRecord::new(root_node_id.clone());
498	        match root_children_override {
499	            Some(children) => {
500	                cipherbox_sdk::rotate_read_from_node_with_root_children(
501	                    &deps,
502	                    &root_node_id,
503	                    grant_root_ipns_name,
504	                    root_read_key.as_slice(),
505	                    &mut job,
506	                    children,
507	                )
508	                .await
509	            }
510	            None => {
511	                cipherbox_sdk::rotate_read_from_node(
512	                    &deps,
513	                    &root_node_id,
514	                    grant_root_ipns_name,
515	                    root_read_key.as_slice(),
516	                    &mut job,
517	                )
518	                .await
519	            }
520	        }
521	    };
522	
523	    match outcome {
524	        Ok(maybe_result) => {
525	            // 70.1-13a (revocation-bypass fix): refresh the grant-root inode's
526	            // in-memory read key so any subsequent local publish reseals under
527	            // the NEW key. `fresh_root` is `None` on a resume-skip; nothing to
528	            // refresh in that case.
529	            if let Some(result) = maybe_result {
530	                refresh_rotated_inode_read_keys(&mut fs.inodes, &result);
531	            }
532	            log::info!(
533	                "shared-scope-exit read-key rotation completed \
534	                 (read-plane grant_root ipns={}, write-plane child_id={})",
535	                grant_root_ipns_name,
536	                deleted_child_id,
537	            );
538	            Ok(())
539	        }
540	        Err(e) => {
541	            log::error!(
542	                "shared-scope-exit read-key rotation FAILED (read-plane grant_root ipns={}, \
543	                 write-plane child_id={}): {} — failing closed",
544	                grant_root_ipns_name,
545	                deleted_child_id,
546	                e,
547	            );
548	            Err(e)
549	        }
550	    }
551	}
