pub(crate) fn poll_filepointer_resolution(fs: &mut crate::CipherBoxFS, ino: u64) -> PollResult {
    use std::time::Duration;
    const FILEPOINTER_POLL_INTERVAL: Duration = Duration::from_millis(100);
    // Bounded number of on-demand re-spawns with the CURRENT inode key. A
    // resolution spawned by the folder-refresh loop captures the file's
    // read_key at spawn time; if a scope-exit rotation re-keys the file while
    // that resolution is in flight, it fails to unseal (stale key) even though
    // `refresh_rotated_inode_read_keys` has already updated the INODE. On such
    // a failure we re-spawn a FRESH resolution reading the file's now-current
    // key (see `CipherBoxFS::spawn_filepointer_resolution`) so a just-rotated
    // file becomes readable — this is what makes a covered overwrite-rename's
    // source `open` succeed on macOS FUSE-T instead of EIO-ing.
    const MAX_FRESH_RESPAWNS: u32 = 3;

    let deadline = std::time::Instant::now() + FILEPOINTER_POLL_TIMEOUT;
    let mut fresh_respawns = 0u32;

    // Helper: has the inode reached the resolved state (non-empty CID)?
    let is_resolved = |fs: &crate::CipherBoxFS| {
        matches!(
            fs.inodes.get(ino).map(|i| &i.kind),
            Some(crate::inode::InodeKind::File { cid, .. }) if !cid.is_empty()
        )
    };

    loop {
        // Nothing in flight: either already resolved, or the last attempt
        // failed. Re-drive ONE fresh resolution with the file's CURRENT
        // (post-rotation) inode key before giving up, up to the cap.
        if !fs.resolving_file_pointers.contains(&ino) {
            if is_resolved(fs) {
                return PollResult::Resolved;
            }
            if fresh_respawns >= MAX_FRESH_RESPAWNS || !fs.spawn_filepointer_resolution(ino) {
                log::debug!(
                    "poll_filepointer_resolution: ino={} unresolved after {fresh_respawns} fresh re-spawns",
                    ino
                );
                return PollResult::NotInFlight;
            }
            fresh_respawns += 1;
        }

        if std::time::Instant::now() >= deadline {
            return PollResult::TimedOut;
        }
        std::thread::sleep(FILEPOINTER_POLL_INTERVAL);
        fs.drain_filepointer_completions();
        if is_resolved(fs) {
            return PollResult::Resolved;
        }
        // If the in-flight resolution just finished as Failure, the top of the
        // loop re-spawns a fresh one with the current key (bounded).
    }
}

