211	    // Expected format: "2026-01-01T00:00:00.000000000Z" (29 chars minimum, ends with Z).
212	    // Tolerate missing nanoseconds: "2026-01-01T00:00:00Z" also valid.
213	    let s = s.strip_suffix('Z')?;
214	    let (date_part, time_part) = s.split_once('T')?;
215	
216	    let mut date_parts = date_part.split('-');
217	    let year: i64 = date_parts.next()?.parse().ok()?;
218	    let month: u32 = date_parts.next()?.parse().ok()?;
219	    let day: u32 = date_parts.next()?.parse().ok()?;
220	    // Reject trailing date components (e.g. "2026-01-01-99").
221	    if date_parts.next().is_some() {
