226	    // all ASCII digits (reject junk like "00:00:00." or extra separators).
227	    let mut dot = time_part.splitn(2, '.');
228	    let time_no_nanos = dot.next()?;
229	    if let Some(frac) = dot.next() {
230	        if frac.is_empty() || !frac.bytes().all(|b| b.is_ascii_digit()) {
231	            return None;
232	        }
233	    }
234	    let mut time_parts = time_no_nanos.split(':');
235	    let hour: u64 = time_parts.next()?.parse().ok()?;
236	    let minute: u64 = time_parts.next()?.parse().ok()?;
237	    let second: u64 = time_parts.next()?.parse().ok()?;
238	    // Reject trailing time components (e.g. "00:00:00:99").
239	    if time_parts.next().is_some() {
