246	    if month < 1 || month > 12 || day < 1 || hour > 23 || minute > 59 || second > 59 {
247	        return None;
248	    }
249	    let is_leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
250	    let days_in_month = match month {
251	        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
252	        4 | 6 | 9 | 11 => 30,
253	        2 => {
254	            if is_leap {
255	                29
256	            } else {
257	                28
258	            }
259	        }
260	        _ => return None,
261	    };
262	    if day > days_in_month {
263	        return None;
264	    }
265	
266	    // Compute days since Unix epoch using the Hinnant civil_from_days algorithm (inverted).
267	    // days_from_civil: given (year, month, day) → days since 1970-01-01.
268	    let (y, m) = if month <= 2 { (year - 1, month + 9) } else { (year, month - 3) };
269	    let era = if y >= 0 { y } else { y - 399 } / 400;
270	    let yoe = (y - era * 400) as u64;
271	    let doy = (153 * m as u64 + 2) / 5 + day as u64 - 1;
272	    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
273	    let days_since_epoch = (era * 146097) as i64 + doe as i64 - 719468;
274	
275	    if days_since_epoch < 0 {
276	        return None; // Pre-epoch timestamp — treat as expired.
277	    }
278	
279	    let total_secs = days_since_epoch as u64 * 86400 + hour * 3600 + minute * 60 + second;
